"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["16053"],{9564(e){e.exports=JSON.parse('{"id":"F517","slug":"multiple-testing-false-positives","name":"Multiple Testing: False Positives and the Bonferroni Correction","subject":"Advanced Investment Practice","section":"Research integrity","topic":"Research integrity","level":"Intermediate","aliases":["research integrity","p-hacking","data mining","backtest overfitting","family-wise error rate"],"formula":{"latex":"FWER=1-(1-\\\\alpha)^{n},\\\\quad \\\\alpha_{adj}=\\\\frac{\\\\alpha}{n},\\\\quad E[\\\\text{false positives}]=n\\\\alpha","also":[],"text":"If you test n unrelated ideas at significance level alpha, the chance of at least one false discovery = 1 - (1 - alpha)^n; Expected number of false positives = n x alpha; Bonferroni-adjusted threshold = alpha / n; A result is credible only if its p-value is below the adjusted threshold; Required t-statistic rises from about 2 to 3 or more when many strategies are tried"},"symbols":[{"symbol":"n","meaning":"Number of strategies, signals or variables tried (including the ones not reported)","unit":"count"},{"symbol":"alpha","meaning":"Significance level used for each test","unit":"percent"},{"symbol":"p","meaning":"p-value of the best result","unit":"number"}],"when_to_use":"Use it to check research for data mining. If you try 40 signals and report the best one, a \\"significant\\" result at 5% is very likely by luck alone. State how many things you tried, adjust the threshold, and test on data not used in the search. The same issue applies to backtests where many rules and parameters were tried.","worked_example":{"problem":"A researcher tries 40 trading signals at the 5% level and reports the best one, which has a p-value of 0.012.","inputs":{"n":40,"a":5,"p":0.012},"steps":[{"label":"Signals tried","working":"40","value":"40"},{"label":"Chance of at least one false positive","working":"1-(1-0.05)^40","value":"87.1%"},{"label":"Expected false positives","working":"40 x 0.05","value":"2.0"},{"label":"Bonferroni-adjusted threshold","working":"0.05 / 40","value":"0.125%"},{"label":"Passes the adjusted threshold? (1 = yes)","working":"1 if 0.012<=0.05 / 40 else 0","value":"0"},{"label":"Adjusted p-value","working":"min(0.012 x 40, 1)","value":"0.480"}],"answer":"The chance that at least one of 40 signals looks significant by luck alone is 87.1%, and the expected number of false positives is 2.0. The adjusted threshold is 0.125%. The reported p-value of 0.012 is 0 (1 = passes the adjusted threshold, 0 = does not). The adjusted p-value (p x n, capped at 1) is 0.480."},"calculator":{"available":true,"inputs":[{"id":"n","label":"Number of signals tried","unit":"count","type":"number","default":40,"hint":"","min":1},{"id":"a","label":"Significance level","unit":"%","type":"number","default":5,"hint":""},{"id":"p","label":"Best p-value (as a decimal, e.g. 0.012)","unit":"","type":"number","default":0.012,"hint":""}],"checks":[{"expr":"n>=1 and p>0 and p<=1","message":"Enter at least one test and a p-value between 0 and 1."}],"steps":[{"id":"n_","label":"Signals tried","expr":"n","format":"num0"},{"id":"fw","label":"Chance of at least one false positive","expr":"1-(1-a)^n","format":"pct1"},{"id":"efp","label":"Expected false positives","expr":"n*a","format":"num1"},{"id":"bon","label":"Bonferroni-adjusted threshold","expr":"a/n","format":"pct3"},{"id":"ok_","label":"Passes the adjusted threshold? (1 = yes)","expr":"1 if p<=a/n else 0","format":"num0"},{"id":"padj","label":"Adjusted p-value","expr":"min(p*n, 1)","format":"num3"}],"results":["fw","efp","bon","ok_","padj"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"n_":40,"fw":0.8714878434348969,"efp":2,"bon":0.00125,"ok_":0,"padj":0.48}},"finder":{"finds":"Whether a best-of-many result could be luck","needs":"Number of tests tried, significance level, best p-value"},"related":[{"slug":"t-statistic","name":"t-Statistic for a Mean (Hypothesis Test)"},{"slug":"fundamental-law-active","name":"Fundamental Law of Active Management"},{"slug":"forecast-calibration","name":"Forecast Calibration and Brier Score"}],"related_ids":["F052","F516","F421"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>F</mi><mi>W</mi><mi>E</mi><mi>R</mi><mo>=</mo><mn>1</mn><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>\u03B1</mi><msup><mo stretchy=\\"false\\">)</mo><mi>n</mi></msup><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mi>\u03B1</mi><mrow><mi>a</mi><mi>d</mi><mi>j</mi></mrow></msub><mo>=</mo><mfrac><mi>\u03B1</mi><mi>n</mi></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>E</mi><mo stretchy=\\"false\\">[</mo><mtext>false\xa0positives</mtext><mo stretchy=\\"false\\">]</mo><mo>=</mo><mi>n</mi><mi>\u03B1</mi></mrow><annotation encoding=\\"application/x-tex\\">FWER=1-(1-\\\\alpha)^{n},\\\\quad \\\\alpha_{adj}=\\\\frac{\\\\alpha}{n},\\\\quad E[\\\\text{false positives}]=n\\\\alpha</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>F</mi><mi>W</mi><mi>E</mi><mi>R</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle FWER</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mn>1</mn><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>\u03B1</mi><msup><mo stretchy=\\"false\\">)</mo><mi>n</mi></msup></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =1-(1-\\\\alpha)^{n}</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><msub><mi>\u03B1</mi><mrow><mi>a</mi><mi>d</mi><mi>j</mi></mrow></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\alpha_{adj}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mfrac><mi>\u03B1</mi><mi>n</mi></mfrac></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\frac{\\\\alpha}{n}</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>E</mi><mo stretchy=\\"false\\">[</mo><mtext>false\xa0positives</mtext><mo stretchy=\\"false\\">]</mo></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle E[\\\\text{false positives}]</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>n</mi><mi>\u03B1</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =n\\\\alpha</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"two-stage-ddm","name":"Multi-Stage Dividend Discount Model (Two Stages)"},"next":{"slug":"muni-tax-equivalent-yield","name":"Municipal Bond Tax-Equivalent Yield (with State Tax)"},"lesson":null,"total":522}')}}]);